# AUTO-GENERATED by Claude Code
# Purpose: tests that every character in char.parquet has a stock icon on disk, and that
#          the `char_icon` column and ds.data.char_icon_path agree (see ds.data.raw.smashmate).
# Usage: uv run pytest tests/ds/data/test_char_icons.py
# ---------------------------------------------------------------------------
from __future__ import annotations

import polars as pl
import pytest
from ds.cli.data import CHAR_PARQUET_PATH, DATA_DIR
from ds.data import CHAR_ICON_DIR, char_icon, char_icon_by_name, char_icon_path
from ds.data.raw.smashmate import PNG_MAGIC, SITE_CHAR_ICON, char_icon_file

CHARS = pl.read_parquet(CHAR_PARQUET_PATH)


def test_every_character_has_an_icon_mapped():
    assert set(CHARS["id"]) == set(SITE_CHAR_ICON)


@pytest.mark.parametrize("char_id", CHARS["id"].to_list())
def test_icon_file_exists_and_is_a_png(char_id):
    path = char_icon_path(char_id)
    assert path.parent == CHAR_ICON_DIR
    assert path.read_bytes().startswith(PNG_MAGIC)


def test_icon_column_matches_the_lookup():
    for char_id, icon in CHARS.select("id", "char_icon").iter_rows():
        assert icon == char_icon(char_id)
        assert DATA_DIR / icon == char_icon_path(char_id)


def test_shared_icons():
    assert {char_icon_file(c) for c in ("pt_squirtle", "pt_ivysaur", "pt_charizard")} == {"pokemon_trainer.png"}
    assert char_icon_file("pyra") == char_icon_file("mythra") == "pyra_mythra.png"
    assert char_icon_file("little_mac") == "little_mac.png"


def test_no_stray_icon_files():
    assert {path.name for path in CHAR_ICON_DIR.glob("*.png")} == {
        char_icon_file(char_id) for char_id in SITE_CHAR_ICON
    }


def test_unknown_char_id():
    with pytest.raises(ValueError, match="no icon for char id"):
        char_icon_path("not_a_character")


@pytest.mark.parametrize(
    ("name", "file"),
    [
        ("Little Mac", "little_mac.png"),
        ("little_mac", "little_mac.png"),
        ("PAC-MAN", "pac_man.png"),
        ("Mr. Game & Watch", "mr_game_and_watch.png"),
        ("Rosalina & Luma", "rosalina_and_luma.png"),
        ("Pokémon Trainer", "pokemon_trainer.png"),
        ("Pyra/Mythra", "pyra_mythra.png"),
        ("R.O.B.", "rob.png"),
    ],
)
def test_icon_by_display_name(name, file):
    assert char_icon_by_name(name) == f"char_icons/{file}"


def test_icon_by_unknown_name():
    assert char_icon_by_name("Not A Character") is None
